#pragma once
#include "kstationMidiInitTask.h"
#include "kstationControllerMidiUtilityTask.h"
#include <optional>
namespace kstation {
class ControllerMidiInitTask final {
 using M=MidiInitTask;using MS=M::Stage;using E=MidiSerialEnableTask;using ES=E::Stage;using U=ControllerMidiUtilityTask;using X=MidiTxResetTask;using XS=X::Stage;using P=MidiParserInitTask;using PS=P::Stage;using C=MidiChannelInitTask;using CS=C::Stage;using F=MidiFill16Task;using FS=F::Stage;using H=MidiHeldInitTask;using HS=H::Stage;using G=MidiGlobalsInitTask;using GS=G::Stage;
public:
 enum class Kind:uint8_t{SerialEnable,Initialize};enum class MaskAction:uint8_t{None,Save,Disable,Restore};
 explicit ControllerMidiInitTask(Kind k){if(k==Kind::SerialEnable)serial_.emplace();else main_.emplace();}
 bool complete()const{return done_;}
 MaskAction maskAction()const{if(utility_)return utility_->saveMask()?MaskAction::Save:utility_->maskInterrupts()?MaskAction::Disable:utility_->restoreMask()?MaskAction::Restore:MaskAction::None;if(tx_){auto s=tx_->stage();return s==XS::SaveMask?MaskAction::Save:s==XS::Mask?MaskAction::Disable:s==XS::RestoreMask?MaskAction::Restore:MaskAction::None;}return MaskAction::None;}
 bool stackWrites()const{if(utility_)return utility_->stackWrites();if(tx_){auto s=tx_->stage();return s==XS::SaveMask||s==XS::SaveWord;}if(fill_||held_||globals_)return false;if(channels_)return channels_->stage()==CS::Fill;if(parser_){auto s=parser_->stage();return s==PS::Channels||s==PS::Held||s==PS::Globals;}if(serial_){auto s=serial_->stage();return s==ES::ResetRx||s==ES::ResetTx;}return main_->stage()!=MS::Return;}
 unsigned nextClocks(int previous=-1)const{if(done_)return 0;if(utility_)return utility_->nextClocks();if(tx_){switch(tx_->stage()){case XS::SaveMask:case XS::RestoreMask:return 9;case XS::SaveWord:case XS::RestoreWord:return 6;case XS::WriteProducer:case XS::WriteConsumer:return 9+bus(tx_->stage()==XS::WriteProducer?0xc492:0xc494,2,previous);case XS::Return:return 7;case XS::Complete:return 0;default:return 3;}}if(fill_){switch(fill_->stage()){case FS::Write:return 3+bus(fill_->address(),1,previous);case FS::Return:return 7;case FS::Complete:return 0;default:return 3;}}if(held_){switch(held_->stage()){case HS::Bind:return 9;case HS::Count:return 6;case HS::Write:return 3+bus(held_->address(),1,previous);case HS::WriteInvalid:return 9+bus(0xcbfe,1,previous);case HS::Return:return 7;case HS::Complete:return 0;default:return 3;}}if(globals_){auto s=globals_->stage();if(s==GS::Return)return 7;if(s==GS::WriteBank||s==GS::WriteNrpn||s==GS::WriteSustain)return 9+bus(s==GS::WriteBank?0xcbff:s==GS::WriteNrpn?0xcc00:0xcc01,1,previous);return s==GS::Complete?0:3;}if(channels_){auto s=channels_->stage();return s==CS::Bind?9:s==CS::Fill?10:s==CS::Return?7:s==CS::AwaitChild||s==CS::Complete?0:3;}if(parser_){auto s=parser_->stage();return s==PS::WriteStatus||s==PS::WriteRemaining||s==PS::WriteInternalStatus||s==PS::WriteInternalRemaining||s==PS::WriteSysex?12:s==PS::Channels||s==PS::Held?10:s==PS::Globals?5:s==PS::Return?7:s==PS::AwaitChild||s==PS::Complete?0:3;}if(serial_){auto s=serial_->stage();return s==ES::WriteControl?4:s==ES::ResetRx||s==ES::ResetTx?10:s==ES::Return?7:s==ES::AwaitChild||s==ES::Complete?0:3;}auto s=main_->stage();return s==MS::Return?7:s==MS::AwaitChild||s==MS::Complete?0:10;}
 template<class R,class W>unsigned advanceBefore(unsigned available,R&&read,W&&write,int previous=-1){auto cost=nextClocks(previous);if(!cost||cost>available)return 0;
  if(utility_){auto n=utility_->advanceBefore(cost,[&](uint32_t a,unsigned end){return read(a,1,end);},[&](uint32_t a,uint8_t v,unsigned end){write(a,v,1,end);});if(utility_->complete()){utility_.reset();resumeOuter();}return n;}
  if(tx_){tx_->advance([&](bool consumer){write(consumer?0xc494:0xc492,0,2,cost);});if(tx_->complete()){tx_.reset();resumeOuter();}return cost;}
  if(fill_){fill_->advance([&](uint32_t a,uint8_t v){write(a,v,1,cost);});if(fill_->complete()){fill_.reset();channels_->resume();}return cost;}
  if(held_){held_->advance([&](uint32_t a,uint8_t v){write(a,v,1,cost);});if(held_->complete()){held_.reset();parser_->resume(P::Child::Held);}return cost;}
  if(globals_){globals_->advance([&](G::Write f,uint8_t v){write(f==G::Write::Bank?0xcbff:f==G::Write::Nrpn?0xcc00:0xcc01,v,1,cost);});if(globals_->complete()){globals_.reset();parser_->resume(P::Child::Globals);}return cost;}
  if(channels_){channels_->advance();if(channels_->awaitingChild()){auto group=channels_->channelGroup();fill_.emplace(0xcad6+16*group,group==0?0x80:group==3?0x7f:0);}if(channels_->complete()){channels_.reset();parser_->resume(P::Child::Channels);}return cost;}
  if(parser_){parser_->advance([&](P::Write f){write(f==P::Write::Status?0xcad1:f==P::Write::Remaining?0xcad2:f==P::Write::InternalStatus?0xcac3:f==P::Write::InternalRemaining?0xcac4:0xcd0e,0,1,cost);});if(parser_->awaitingChild()){auto ch=parser_->child();if(ch==P::Child::Channels)channels_.emplace();else if(ch==P::Child::Held)held_.emplace();else globals_.emplace();}if(parser_->complete()){parser_.reset();resumeOuter();}return cost;}
  if(serial_){serial_->advance([&](){write(0xffffb2,0x70,1,cost);});if(serial_->awaitingChild()){if(serial_->child()==E::Child::ResetRx)utility_.emplace(U::Kind::ResetExternal);else tx_.emplace();}done_=serial_->complete();return cost;}
  main_->advance();if(main_->awaitingChild()){auto ch=main_->child();if(ch==M::Child::ResetRx)utility_.emplace(U::Kind::ResetExternal);else if(ch==M::Child::ResetTx)tx_.emplace();else if(ch==M::Child::ResetInternal)utility_.emplace(U::Kind::ResetInternal);else parser_.emplace();}done_=main_->complete();return cost;
 }
private:void resumeOuter(){if(serial_)serial_->resume(serial_->child());else main_->resume(main_->child());}static unsigned bus(uint32_t a,unsigned n,int p){unsigned cost=0;for(unsigned i=0;i<n;++i){auto q=(a+i)&0xffffff;if(q<0x400000||(q>=0xfffd10&&q<0xffffa0)){if((p&1)||q!=uint32_t(p|1))cost+=q<0x400000?3:1;p=int(q);}else{cost+=q>=0xffffa0?1:3;p=-1;}}return cost;}
 bool done_=false;std::optional<M>main_{};std::optional<E>serial_{};std::optional<U>utility_{};std::optional<X>tx_{};std::optional<P>parser_{};std::optional<C>channels_{};std::optional<F>fill_{};std::optional<H>held_{};std::optional<G>globals_{};
};
}
